import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>();
        names.add("{w1}");
        names.add("{w2}");
        names.add("{w3}");
        names.add("{w4}");

        Iterator<String> it = names.iterator();
        while (it.hasNext()) {
            String name = it.next();
            if (name.equals("{w2}")) {
                it.remove();
            }
        }
        System.out.println(names);
    }
}
